effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode

// Os RTs do Node: luz linear, cor pré-multiplicada.
vec3 nvLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c)); }
vec3 nvGama(vec3 l) { return mix(l * 12.92, 1.055 * pow(l, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), l)); }
vec4 nvNode(vec4 c) { return vec4(nvLinear(c.rgb) * c.a, c.a); }
vec4 nvNova(vec4 p) {
    if (p.a <= 0.0) return vec4(0.0);
    return vec4(nvGama(clamp(p.rgb / p.a, 0.0, 1.0)), p.a);
}

// O quadro que o anel não tem chega 1x1 (a textura transparente do FrameHistory).
bool nvTem(ivec2 tamanho) { return tamanho.x > 1 || tamanho.y > 1; }

int nvContagem() { return clamp(int(_slice_count), 1, 30); }

// A faixa do pixel (o u_xlati0 do Node) e a fração dentro dela.
int nvFaixa(vec2 uv, out float fracao) {
    vec2 p = (uv - 0.5) * _viewport_ratio.xy;
    float a = _slice_angle * 0.0174532924;
    float x = float(nvContagem()) * (dot(vec2(sin(a), cos(a)), p) + 0.5);
    fracao = fract(x);
    return int(floor(x));
}

// Quantos quadros atrás está a fatia k: t + (offset + intervalo x (k + 1 - c)) / FPS; o offset positivo (o futuro)
// vira atraso da saída inteira.
int nvAtras(int k) {
    int c = nvContagem();
    int off = int(_frame_offset);
    return int(_frame_interval) * (c - 1 - k) - off + max(off, 0);
}

// Dos 12 mais novos: o quadro `atras` (até 12), ou o mais velho que houver até ele.
vec4 nvPerto(int atras, vec2 uv) {
    if (atras >= 12 && nvTem(textureSize(h12, 0))) return texture(h12, uv);
    if (atras >= 11 && nvTem(textureSize(h11, 0))) return texture(h11, uv);
    if (atras >= 10 && nvTem(textureSize(h10, 0))) return texture(h10, uv);
    if (atras >= 9 && nvTem(textureSize(h9, 0))) return texture(h9, uv);
    if (atras >= 8 && nvTem(textureSize(h8, 0))) return texture(h8, uv);
    if (atras >= 7 && nvTem(textureSize(h7, 0))) return texture(h7, uv);
    if (atras >= 6 && nvTem(textureSize(h6, 0))) return texture(h6, uv);
    if (atras >= 5 && nvTem(textureSize(h5, 0))) return texture(h5, uv);
    if (atras >= 4 && nvTem(textureSize(h4, 0))) return texture(h4, uv);
    if (atras >= 3 && nvTem(textureSize(h3, 0))) return texture(h3, uv);
    if (atras >= 2 && nvTem(textureSize(h2, 0))) return texture(h2, uv);
    if (atras >= 1 && nvTem(textureSize(h1, 0))) return texture(h1, uv);
    return texture(inputImg, uv);
}

// Dos 13..23: o quadro `atras` (preso em 23) ou o mais velho que houver até o 13; sem nenhum, `perto`.
vec4 nvLonge(int atras, vec2 uv, vec4 perto) {
    if (atras >= 23 && nvTem(textureSize(h23, 0))) return texture(h23, uv);
    if (atras >= 22 && nvTem(textureSize(h22, 0))) return texture(h22, uv);
    if (atras >= 21 && nvTem(textureSize(h21, 0))) return texture(h21, uv);
    if (atras >= 20 && nvTem(textureSize(h20, 0))) return texture(h20, uv);
    if (atras >= 19 && nvTem(textureSize(h19, 0))) return texture(h19, uv);
    if (atras >= 18 && nvTem(textureSize(h18, 0))) return texture(h18, uv);
    if (atras >= 17 && nvTem(textureSize(h17, 0))) return texture(h17, uv);
    if (atras >= 16 && nvTem(textureSize(h16, 0))) return texture(h16, uv);
    if (atras >= 15 && nvTem(textureSize(h15, 0))) return texture(h15, uv);
    if (atras >= 14 && nvTem(textureSize(h14, 0))) return texture(h14, uv);
    if (atras >= 13 && nvTem(textureSize(h13, 0))) return texture(h13, uv);
    return perto;
}

// O programa do Node para _cur_slice = cur, conta por conta (o peso da fonte no pixel).
float nvPeso(int u_xlati0, float fracao, int cur) {
    float u_xlat3 = fracao + -1.0;
    float u_xlat6 = float(1.0) / (-_feather);
    u_xlat3 = u_xlat6 * u_xlat3;
    u_xlat3 = clamp(u_xlat3, 0.0, 1.0);
    u_xlat6 = u_xlat3 * -2.0 + 3.0;
    u_xlat3 = u_xlat3 * u_xlat3;
    float u_xlat9 = u_xlati0 == cur ? 1.0 : 0.0;
    u_xlat3 = (-u_xlat6) * u_xlat3 + u_xlat9;
    u_xlat3 = u_xlat3 + 1.0;
    return (cur - 1 == u_xlati0) ? u_xlat3 : u_xlat9;
}

// Uma passada do Node: o shader (fonte x peso + RT x (1 - peso)) e a mistura SrcAlpha OneMinusSrcAlpha num RT de 8 bits.
vec4 nvPassada(vec4 fonte, vec4 rt, float peso) {
    vec4 o = clamp(fonte * peso + rt * (1.0 - peso), 0.0, 1.0);
    return clamp(o * o.a + rt * (1.0 - o.a), 0.0, 1.0);
}

void main()
{
    vec2 uv = acScreenNorm;
    float fracao;
    int s = nvFaixa(uv, fracao);
    int c = nvContagem();

    if (acPass == 0) {
        fragColor = nvPerto(nvAtras(s), uv);
        return;
    }
    if (acPass == 1) {
        fragColor = nvPerto(nvAtras(min(s + 1, c - 1)), uv);
        return;
    }

    vec4 saida = vec4(0.0);
    if (s >= 0 && s < c) {
        // _cur_slice = s: a fatia do pixel
        vec4 f0 = nvNode(nvLonge(nvAtras(s), uv, texture(perto0, uv)));
        saida = nvPassada(f0, saida, nvPeso(s, fracao, s));
        // _cur_slice = s + 1: a suavização da seguinte
        if (s + 1 < c) {
            vec4 f1 = nvNode(nvLonge(nvAtras(s + 1), uv, texture(perto1, uv)));
            saida = nvPassada(f1, saida, nvPeso(s, fracao, s + 1));
        }
    }
    fragColor = nvNova(saida);
}
